import{_ as e,o as n,c as t,a3 as s}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"插件生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugin-lifecycle.md","filePath":"guide/plugin-lifecycle.md","lastUpdated":1787901540000}'),i={name:"guide/plugin-lifecycle.md"};function d(l,a,p,o,c,r){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="插件生命周期" tabindex="-1">插件生命周期 <a class="header-anchor" href="#插件生命周期" aria-label="Permalink to &quot;插件生命周期&quot;">​</a></h1><h2 id="插件包结构" tabindex="-1">插件包结构 <a class="header-anchor" href="#插件包结构" aria-label="Permalink to &quot;插件包结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my_plugin/</span></span>
<span class="line"><span>  __init__.py</span></span>
<span class="line"><span>  plugin.py          # PluginInterface 实现</span></span>
<span class="line"><span>  plugin.json        # name / display_name / version / entry</span></span>
<span class="line"><span>  api.py             # 可选：FastAPI 路由</span></span>
<span class="line"><span>  models.py          # 可选：插件 ORM 模型</span></span>
<span class="line"><span>  migrations/        # 可选：插件迁移</span></span>
<span class="line"><span>  frontend/          # 可选：插件 Vue 页面</span></span>
<span class="line"><span>  static/            # 可选：插件静态资源</span></span></code></pre></div><p>插件名必须是合法 Python 包名。<code>plugin.json.entry</code> 应指向唯一入口类，例如 <code>plugin.MyPlugin</code>；不要在同一个包中放置多个未明确入口的 <code>PluginInterface</code> 实现。</p><h2 id="运行时状态" tabindex="-1">运行时状态 <a class="header-anchor" href="#运行时状态" aria-label="Permalink to &quot;运行时状态&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>discovered → installing → active</span></span>
<span class="line"><span>                    └──→ failed</span></span>
<span class="line"><span>active ──disable──→ inactive</span></span>
<span class="line"><span>active ──uninstall→ removed</span></span></code></pre></div><p>管理器使用锁保护同一插件的操作，并跟踪插件注册的路由、MCP 工具和事件监听器。停用时先调用插件的 <code>unregister()</code>，再移除可跟踪的运行时资源；启用时重新注册这些资源。</p><h2 id="hook-责任" tabindex="-1">Hook 责任 <a class="header-anchor" href="#hook-责任" aria-label="Permalink to &quot;Hook 责任&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hook</th><th>责任</th></tr></thead><tbody><tr><td><code>on_load()</code></td><td>模块加载后的轻量初始化，不应依赖请求上下文</td></tr><tr><td><code>install()</code></td><td>建表、执行迁移、种子数据；必须可重复执行</td></tr><tr><td><code>register(app)</code></td><td>注册路由、静态目录、MCP 工具或事件</td></tr><tr><td><code>unregister(app)</code></td><td>主动释放插件创建的运行时资源</td></tr><tr><td><code>uninstall()</code></td><td>按明确策略删除插件拥有的数据和资源</td></tr><tr><td><code>on_unload()</code></td><td>清理进程内对象和缓存</td></tr></tbody></table><h2 id="菜单与页面契约" tabindex="-1">菜单与页面契约 <a class="header-anchor" href="#菜单与页面契约" aria-label="Permalink to &quot;菜单与页面契约&quot;">​</a></h2><p>后台菜单的 <code>component</code> 必须和实际 Vue 文件一一对应。组件、菜单和权限标识必须作为同一个插件版本交付，不能注册规划中或占位页面。</p><h2 id="升级与失败处理" tabindex="-1">升级与失败处理 <a class="header-anchor" href="#升级与失败处理" aria-label="Permalink to &quot;升级与失败处理&quot;">​</a></h2><p>升级前先停用旧版本，保留数据库和上传文件；新版本安装失败时恢复插件目录和运行时状态。迁移脚本必须提供向前兼容策略，不能依赖回滚数据库来撤销已经发布的数据。</p>`,13)])])}const g=e(i,[["render",d]]);export{u as __pageData,g as default};
